-- Add photographed colors only to the original local sample catalog. Keep existing variant IDs and stock.
UPDATE product_variant SET color='Xanh Navy', image_url='/assets/photos/product-1.jpg' WHERE product_id=1 AND sku IN ('FRM-1-S','FRM-1-M','FRM-1-L','FRM-1-XL') AND image_url IS NULL AND EXISTS (SELECT 1 FROM product p WHERE p.product_id = 1 AND p.brand = 'FORME' AND p.product_name IN ('Áo kiểu cổ nhún cài cúc', 'Áo kiểu cổ nhún buộc dây dài tay') AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=p.product_id AND i.image_url IN ('/assets/photos/product-1.jpg', '/assets/photos/product-1.jpg')));
UPDATE product_image SET image_url='/assets/photos/product-1.jpg' WHERE product_id=1 AND image_url='/assets/photos/product-1.jpg' AND EXISTS (SELECT 1 FROM product p WHERE p.product_id = 1 AND p.brand = 'FORME' AND p.product_name IN ('Áo kiểu cổ nhún cài cúc', 'Áo kiểu cổ nhún buộc dây dài tay'));
